"use strict";

const babelJest = require("babel-jest");

function normalizeJestOptions(configString, options) {
  const normalizedOptions = Object.assign({}, options);
  let config = normalizedOptions.config;

  if (!config && configString) {
    try {
      config = JSON.parse(configString);
    } catch (error) {
      config = {};
    }
  }

  config = Object.assign({}, config);
  config.rootDir = config.rootDir || normalizedOptions.rootDir || process.cwd();
  config.cwd = config.cwd || config.rootDir;

  normalizedOptions.config = config;
  normalizedOptions.rootDir = normalizedOptions.rootDir || config.rootDir;

  return normalizedOptions;
}

function normalizeJestConfig(config) {
  const normalizedConfig = Object.assign({}, config);
  normalizedConfig.rootDir = normalizedConfig.rootDir || process.cwd();
  normalizedConfig.cwd = normalizedConfig.cwd || normalizedConfig.rootDir;
  return normalizedConfig;
}

function createTransformer(options) {
  const transformer =
    typeof babelJest.createTransformer === "function"
      ? babelJest.createTransformer(options)
      : babelJest;

  return {
    canInstrument: transformer.canInstrument,

    getCacheKey(fileData, filename, configString, transformOptions) {
      return transformer.getCacheKey(
        fileData,
        filename,
        configString,
        normalizeJestOptions(configString, transformOptions)
      );
    },

    process(src, filename, config, transformOptions) {
      return transformer.process(
        src,
        filename,
        normalizeJestConfig(config),
        normalizeJestOptions(JSON.stringify(config || {}), transformOptions)
      );
    }
  };
}

module.exports = createTransformer();
module.exports.createTransformer = createTransformer;
